/bin/bash -lc "ls -1 /opt/conda/bin | rg 'para|vtk|ttk' | head -80; find /opt/conda -type f -name 'pvpython*' -o -name 'paraview*' | head -40; python - <<'PY'
try:
 import vtk
 print('vtk', vtk.vtkVersion.GetVTKVersion())
except Exception as e: print(e)
try:
 import paraview
 print('paraview',paraview.__file__)
except Exception as e: print('pv',e)
PY"

