/bin/bash -lc "/opt/conda/bin/pvpython - <<'PY'
from paraview.simple import *
for n in ['TTKTopologicalSimplification','TTKTopologicalSimplificationByPersistence','TTKContourTree']:
 try:
  x=globals()[n]()
  print('\\n',n)
  print(x.ListProperties())
 except Exception as e: print(e)
PY"

